2	/// Belnap FOUR truth values.
3	#[derive(Copy, Clone, PartialEq, Eq, Debug, Hash)]
4	#[repr(u8)]
5	pub enum B4 {
6	    N = 0, // None  — void, absence
7	    T = 1, // True  — affirmation
8	    F = 2, // False — negation
9	    B = 3, // Both  — paradox stabilized
10	}
