12	impl B4 {
13	    pub fn name(self) -> &'static str {
14	        match self { B4::N => "N", B4::T => "T", B4::F => "F", B4::B => "B" }
15	    }
16	
17	    pub fn from_u8(v: u8) -> Self {
18	        match v & 0b11 { 1 => B4::T, 2 => B4::F, 3 => B4::B, _ => B4::N }
19	    }
20	
21	    pub fn to_u8(self) -> u8 { self as u8 }
22	
23	    /// Truth-order meet (greatest lower bound): bitwise AND.
24	    pub fn meet(self, other: B4) -> B4 {
25	        B4::from_u8(self as u8 & other as u8)
26	    }
27	
28	    /// Truth-order join (least upper bound): bitwise OR.
29	    pub fn join(self, other: B4) -> B4 {
30	        B4::from_u8(self as u8 | other as u8)
31	    }
32	
33	    /// Knowledge-order consensus (lub in ≤k): bitwise OR = join.
34	    /// T ⊗ F = B (both affirmations → paradox).
35	    pub fn band(self, other: B4) -> B4 { self.join(other) }
36	
37	    /// Knowledge-order gullibility (glb in ≤k): bitwise AND = meet.
38	    /// T ⊕ F = N (no shared ground).
39	    pub fn bor(self, other: B4) -> B4 { self.meet(other) }
40	
41	    /// Truth-functional conjunction — the bilattice's *other* axis.
42	    /// Mirrors `Belnap.lean` `band` and `belnap.py` `band`: F absorbs,
43	    /// B absorbs N. Distinct from `band` above, which is the knowledge
44	    /// consensus: T ∧ F = F here, where T ⊗ F = B there.
45	    pub fn truth_and(self, other: B4) -> B4 {
46	        use B4::*;
47	        match (self, other) {
48	            (F, _) | (_, F) => F,
49	            (B, T) | (T, B) | (B, N) | (N, B) => B,
50	            (T, T) => T,
51	            (T, N) | (N, T) => N,
52	            (N, N) => N,
53	            (B, B) => B,
54	        }
55	    }
56	
57	    /// Truth-functional disjunction. Mirrors `Belnap.lean` `bor`:
58	    /// T absorbs, B absorbs N. T ∨ F = T here, where T ⊕ F = N for `bor`.
59	    pub fn truth_or(self, other: B4) -> B4 {
60	        use B4::*;
61	        match (self, other) {
62	            (T, _) | (_, T) => T,
63	            (B, F) | (F, B) | (B, N) | (N, B) => B,
64	            (F, F) => F,
65	            (F, N) | (N, F) => N,
66	            (N, N) => N,
67	            (B, B) => B,
68	        }
69	    }
70	
71	    /// Negation: swap T↔F, preserve N and B.
72	    pub fn bnot(self) -> B4 {
73	        let b = self as u8;
74	        B4::from_u8(((b & 1) << 1) | ((b & 2) >> 1))
75	    }
76	
77	    /// Is this value paradox-stabilized (Both)?
78	    pub fn dialetheic(self) -> bool { self == B4::B }
79	
80	    /// Is this value designated (T or B) in Belnap logic?
81	    pub fn designated(self) -> bool { matches!(self, B4::T | B4::B) }
82	
83	    /// Knowledge-order comparison: self ≤k other.
84	    /// x ≤k y iff x ⊓k y = x, and the knowledge glb is `meet`.
85	    pub fn approx_le(self, other: B4) -> bool {
86	        self.meet(other) == self
87	    }
88	
89	    /// Encode to WH2 pair: (is_true, is_false).
90	    pub fn to_wh2(self) -> (bool, bool) {
91	        let b = self as u8;
92	        ((b & 1) != 0, (b & 2) != 0)
93	    }
94	
95	    /// Decode from WH2 pair.
96	    pub fn from_wh2(t: bool, f: bool) -> Self {
97	        B4::from_u8((t as u8) | ((f as u8) << 1))
98	    }
99	}
