101	// ── The Boolean core's two adjoints, and the closure they can't reach ──
102	//
103	// UNO_Reverse.tex: the inclusion of the Boolean core B_4={F,T} into FOUR
104	// has a left adjoint (reflector r) and a right adjoint (coreflector c),
105	// not the same map -- checked directly against the manuscript's own
106	// theorems, not read off a summary: line ~419 "r(F)=F, r(N)=r(B)=T" (the
107	// truth-order reflection theorem, proved by cases at F and T); the
108	// coreflection theorem gives c(N)=c(B)=F by the dual argument, c(T)=T.
109	// `Inc(v)=B` is the paraconsistent closure: constant, image {B}, a fixed
110	// point (`Inc(B)=B`) outside the Boolean core, idempotent.
111	//
112	// Naming note: the manuscript's "B_4" names the two-element classical
113	// SUBSET {F,T} of FOUR. This file's `B4` type is the full four-valued
114	// carrier {N,T,F,B}. Same three letters, two different objects -- do not
115	// conflate this type with the paper's classical core when reading the
116	// functions below.
117	
118	/// The reflector: the least Boolean value above v in the truth order.
119	/// Sends every nonclassical value (N, B) up to T; T and F are fixed.
120	pub fn r(v: B4) -> B4 {
121	    if v == B4::F { B4::F } else { B4::T }
122	}
123	
124	/// The coreflector: the greatest Boolean value below v in the truth
125	/// order. Sends every nonclassical value (N, B) down to F; T and F are
126	/// fixed. The same two inputs (N, B) that `r` sends to T, `c` sends to
127	/// F -- the manuscript's "erase the same nonclassical values in opposite
128	/// directions" theorem, checked below in `theorem_5_5_report`.
129	pub fn c(v: B4) -> B4 {
130	    if v == B4::T { B4::T } else { B4::F }
131	}
132	
133	/// The paraconsistent closure: constant at B, for every input. Not a
134	/// retraction into the Boolean core -- its one output value sits outside
135	/// {T, F} entirely, which is the whole content of Corollary 11.2 below:
136	/// no Boolean endomap (certainly not r or c) can undo this constancy and
137	/// recover what v was.
138	pub fn inc(_v: B4) -> B4 {
139	    B4::B
140	}
141	
142	/// Corollary 11.2 (UNO_Reverse.tex, the corollary right after the
143	/// retraction-square figure): r∘Inc and c∘Inc are constant maps, T and F
144	/// respectively, and neither recovers Inc(v)=B. Checked exhaustively over
145	/// all four inputs -- only four to check, so "exhaustive" here is a real
146	/// claim, not a sampling one.
147	pub fn corollary_11_2_report() -> alloc::string::String {
148	    use alloc::format;
149	    use alloc::string::String;
150	    let mut out = String::new();
151	    let mut r_inc_constant = true;
152	    let mut c_inc_constant = true;
153	    for v in [B4::N, B4::T, B4::F, B4::B] {
154	        let ri = r(inc(v));
155	        let ci = c(inc(v));
156	        if ri != B4::T { r_inc_constant = false; }
157	        if ci != B4::F { c_inc_constant = false; }
158	        out.push_str(&format!(
159	            "  v={:<2} Inc(v)={:<2} r(Inc(v))={:<2} c(Inc(v))={:<2}\n",
160	            v.name(), inc(v).name(), ri.name(), ci.name()
161	        ));
162	    }
163	    out.push_str(&format!(
164	        "  r∘Inc constant at T over all 4 inputs: {}\n",
165	        r_inc_constant
166	    ));
167	    out.push_str(&format!(
168	        "  c∘Inc constant at F over all 4 inputs: {}\n",
169	        c_inc_constant
170	    ));
171	    out.push_str("  neither equals Inc(v)=B for any v: true by inspection (T≠B, F≠B)\n");
172	    out
173	}
174	
175	/// Theorem 5.5 in the YZ-retranslation document's numbering (the paper's
176	/// own "the two universal collapses are distinct" theorem in
177	/// UNO_Reverse.tex): r and c send the same two nonclassical inputs to
178	/// opposite classical outputs, and agree on the two classical inputs.
179	pub fn theorem_5_5_report() -> alloc::string::String {
180	    use alloc::format;
181	    use alloc::string::String;
182	    let mut out = String::new();
183	    let mut opposite_on_nonclassical = true;
184	    let mut agree_on_classical = true;
185	    for v in [B4::N, B4::T, B4::F, B4::B] {
186	        let rv = r(v);
187	        let cv = c(v);
188	        let nonclassical = matches!(v, B4::N | B4::B);
189	        if nonclassical && rv == cv { opposite_on_nonclassical = false; }
190	        if !nonclassical && rv != cv { agree_on_classical = false; }
191	        out.push_str(&format!("  v={:<2} r(v)={:<2} c(v)={:<2}\n", v.name(), rv.name(), cv.name()));
192	    }
193	    out.push_str(&format!(
194	        "  r and c disagree on both nonclassical inputs (N, B): {}\n",
195	        opposite_on_nonclassical
196	    ));
197	    out.push_str(&format!(
198	        "  r and c agree on both classical inputs (T, F): {}\n",
199	        agree_on_classical
200	    ));
201	    out
202	}
