224	/// 4096-cell B4 memory, 2 bits per cell packed into a byte array.
225	pub struct B4Memory {
226	    data: [u8; 1024], // 4096 cells × 2 bits = 1024 bytes
227	}
228	
229	impl B4Memory {
230	    pub const fn new() -> Self {
231	        Self { data: [0u8; 1024] }
232	    }
233	
234	    pub fn read(&self, addr: usize) -> B4 {
235	        let addr = addr & 0xFFF;
236	        let byte = self.data[addr / 4];
237	        let shift = (addr % 4) * 2;
238	        B4::from_u8((byte >> shift) & 0b11)
239	    }
240	
241	    pub fn write(&mut self, addr: usize, val: B4) {
242	        let addr = addr & 0xFFF;
243	        let shift = (addr % 4) * 2;
244	        let mask = !(0b11u8 << shift);
245	        self.data[addr / 4] = (self.data[addr / 4] & mask) | ((val as u8) << shift);
246	    }
247	}
248	
249	/// 256-deep B4 stack.
250	pub struct B4Stack {
251	    data: [B4; 256],
252	    top: usize,
253	}
254	
255	impl B4Stack {
256	    pub const fn new() -> Self {
257	        Self { data: [B4::N; 256], top: 0 }
258	    }
259	
260	    pub fn push(&mut self, v: B4) {
261	        if self.top < 256 {
262	            self.data[self.top] = v;
263	            self.top += 1;
264	        }
265	    }
266	
267	    pub fn pop(&mut self) -> B4 {
268	        if self.top == 0 { return B4::N; }
269	        self.top -= 1;
270	        self.data[self.top]
271	    }
272	
273	    pub fn peek(&self) -> B4 {
274	        if self.top == 0 { B4::N } else { self.data[self.top - 1] }
275	    }
276	
277	    pub fn peek_at(&self, offset: usize) -> B4 {
278	        if offset >= self.top { B4::N } else { self.data[offset] }
279	    }
280	
281	    pub fn depth(&self) -> usize { self.top }
282	
283	    pub fn clear(&mut self) { self.top = 0; }
284	
285	    /// ROTAT — cyclic shift of the stack by k positions (mod depth).
286	    /// The element at position i moves to position (i + k) % depth.
287	    pub fn rotate(&mut self, k: usize) {
288	        let n = self.top;
289	        if n <= 1 { return; }
290	        let k = k % n;
291	        if k == 0 { return; }
292	        // Cyclic shift right by k: reverse whole, reverse first k, reverse rest
293	        self.data[..n].reverse();
294	        self.data[..k].reverse();
295	        self.data[k..n].reverse();
296	    }
297	
298	}
