300	/// 8 × B4 register file.
301	pub struct B4Registers {
302	    regs: [B4; 8],
303	    pub engagr: bool,
304	}
305	
306	impl B4Registers {
307	    pub const fn new() -> Self {
308	        Self { regs: [B4::N; 8], engagr: false }
309	    }
310	
311	    pub fn read(&self, i: usize) -> B4 { self.regs[i & 7] }
312	
313	    pub fn write(&mut self, i: usize, v: B4) { self.regs[i & 7] = v; }
314	
315	    pub fn clear(&mut self) {
316	        self.regs = [B4::N; 8];
317	        self.engagr = false;
318	    }
319	}
