321	// ── Module-level self-verification ──────────────────────────────
322	#[test]
323	fn belnap_invariants() {
324	    use B4::*;
325	    // Frobenius: join(B, x) = B  ∀x (B absorbs join)
326	    for &x in &[N, T, F, B] { assert_eq!(B.join(x), B); }
327	    // B meet = identity
328	    for &x in &[N, T, F, B] { assert_eq!(B.meet(x), x); }
329	    // B fixed-point negation
330	    assert_eq!(B.bnot(), B);
331	    // N fixed-point negation
332	    assert_eq!(N.bnot(), N);
333	    // T↔F swap
334	    assert_eq!(T.bnot(), F);
335	    assert_eq!(F.bnot(), T);
336	    // bnot(bnot(x)) = x
337	    for &x in &[N, T, F, B] { assert_eq!(x.bnot().bnot(), x); }
338	    // dialetheic: only B
339	    assert!(B.dialetheic());
340	    assert!(!N.dialetheic() && !T.dialetheic() && !F.dialetheic());
341	    // designated: T and B
342	    assert!(T.designated() && B.designated());
343	    assert!(!N.designated() && !F.designated());
344	    // WH2 round-trip
345	    for &x in &[N, T, F, B] {
346	        let (t, f) = x.to_wh2();
347	        assert_eq!(B4::from_wh2(t, f), x);
348	    }
349	    // approx_le: N ≤k everything, everything ≤k B
350	    for &x in &[N, T, F, B] {
351	        assert!(N.approx_le(x));
352	        assert!(x.approx_le(B));
353	    }
354	    // band: T ⊗ F = B, N ⊗ x = x
355	    assert_eq!(T.band(F), B);
356	    assert_eq!(N.band(T), T);
357	    // bor: T ⊕ F = N, B ⊕ x = x
358	    assert_eq!(T.bor(F), N);
359	    assert_eq!(B.bor(T), T);
360	    // The two axes are different operations, and nothing above would catch
361	    // one being reached for in place of the other. T ∧ F = F and T ∨ F = T
362	    // on the truth axis, against T ⊗ F = B and T ⊕ F = N on the knowledge one.
363	    assert_eq!(T.truth_and(F), F);
364	    assert_eq!(T.truth_or(F), T);
365	    assert_ne!(T.truth_and(F), T.band(F));
366	    assert_ne!(T.truth_or(F), T.bor(F));
367	    // B absorbs N on both truth operations; F and T absorb respectively.
368	    assert_eq!(B.truth_and(N), B);
369	    assert_eq!(B.truth_or(N), B);
370	    for &x in &[N, T, F, B] {
371	        assert_eq!(F.truth_and(x), F);
372	        assert_eq!(T.truth_or(x), T);
373	        assert_eq!(x.truth_and(x), x);
374	        assert_eq!(x.truth_or(x), x);
375	    }
376	}
